package com.vibeguard.samples.notifications;
import java.net.URI; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.util.HexFormat; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
/** Sends signed test notifications to a configured webhook. */ @RestController @RequestMapping("/internal/notifications") public class NotificationController { private final HttpClient client=HttpClient.newHttpClient(); @Value("${NOTIFICATION_WEBHOOK_URL:}") private String webhookUrl; @Value("${NOTIFICATION_WEBHOOK_SIGNING_SECRET:}") private String signingSecret;
 @PostMapping("/test") public ResponseEntity<Delivery> test() throws Exception {if(webhookUrl.isBlank()||signingSecret.isBlank())return ResponseEntity.status(503).build();String body="{\"event\":\"test.notification\"}";HttpRequest request=HttpRequest.newBuilder(URI.create(webhookUrl)).header("Content-Type","application/json").header("X-Webhook-Signature",signature(body)).POST(HttpRequest.BodyPublishers.ofString(body)).build();HttpResponse<Void> response=client.send(request,HttpResponse.BodyHandlers.discarding());return ResponseEntity.ok(new Delivery(response.statusCode()));} private String signature(String body)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(signingSecret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(body.getBytes(StandardCharsets.UTF_8)));} record Delivery(int statusCode){} }
